//! The committed vector files.
//!
//! Line format (`#` starts a comment): `<TypeName>.<tag> | <hex>`.
//! * `messages.txt`: the complete `NGAP-PDU` (initiating message / successful outcome / unsuccessful outcome of a
//!   procedure) whose message type is `TypeName`; tags `min`, `max`, `r1`, `r2`, `r3`.
//! * `types.txt`: every named type standalone (`TypeName` as in the ASN.1); tags `min`, `max`, `r1`.

use std::fmt::Write as _;

use ngap_codegen::ir::{Ir, IrType};

use crate::rng::hash;
use crate::sampler::{Mode, SampleError, Sampler};

/// The two generated files.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Vectors {
    pub messages: String,
    pub types: String,
}

const MESSAGE_TAGS: [(&str, Mode, u64); 5] = [
    ("min", Mode::Min, 0),
    ("max", Mode::Max, 0),
    ("r1", Mode::Random, 1),
    ("r2", Mode::Random, 2),
    ("r3", Mode::Random, 3),
];
const TYPE_TAGS: [(&str, Mode, u64); 3] = [
    ("min", Mode::Min, 0),
    ("max", Mode::Max, 0),
    ("r1", Mode::Random, 1),
];

fn hex(b: &[u8]) -> String {
    let mut s = String::with_capacity(b.len() * 2);
    for x in b {
        let _ = write!(s, "{x:02x}");
    }
    s
}

pub fn generate(ir: &Ir) -> Result<Vectors, SampleError> {
    let mut messages = String::from(
        "# Generated by `cargo xtask vectors` (crates/ngap-testgen). Do not edit.\n\
         # `<message type>.<tag> | <hex of the complete NGAP-PDU>`; min/max/r1..r3 are sampling modes.\n",
    );
    for p in &ir.procedures {
        for role in 0..3 {
            let name = match role {
                0 => Some(&p.initiating),
                1 => p.successful.as_ref(),
                _ => p.unsuccessful.as_ref(),
            };
            let Some(name) = name else { continue };
            if !Sampler::new(ir, Mode::Min, 0).can_sample(&IrType::Named(name.clone())) {
                // e.g. PrivateMessage: its container needs one private IE and the specification defines none
                let _ = writeln!(messages, "# {name}: no value can be sampled (empty IE set)");
                continue;
            }
            for (tag, mode, n) in MESSAGE_TAGS {
                let mut s = Sampler::new(ir, mode, hash(name) ^ n);
                let (_, bytes) = s
                    .pdu(p, role)
                    .map_err(|e| SampleError(format!("{name}.{tag}: {e}")))?
                    .ok_or_else(|| SampleError(format!("{name}: no message")))?;
                let _ = writeln!(messages, "{name}.{tag} | {}", hex(&bytes));
            }
        }
    }

    let mut types = String::from(
        "# Generated by `cargo xtask vectors` (crates/ngap-testgen). Do not edit.\n\
         # `<type>.<tag> | <hex of the standalone APER encoding>`; types whose encoding is empty are left out.\n",
    );
    for t in &ir.types {
        let mut probe = Sampler::new(ir, Mode::Min, 0);
        if !probe.can_sample(&IrType::Named(t.name.clone())) {
            continue;
        }
        for (tag, mode, n) in TYPE_TAGS {
            let mut s = Sampler::new(ir, mode, hash(&t.name) ^ n);
            let bytes = s
                .named(&t.name)
                .map_err(|e| SampleError(format!("{}.{tag}: {e}", t.name)))?;
            if !bytes.is_empty() {
                let _ = writeln!(types, "{}.{tag} | {}", t.name, hex(&bytes));
            }
        }
    }
    Ok(Vectors { messages, types })
}
